package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamDiseaseAyurvedaBank1 {
    private const val T = "බෝවන හා බෝ නොවන රෝග, ප්‍රජා සෞඛ්‍යය හා හෙළ වෙදකම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ඩෙංගු උණ රෝගය මිනිසාගෙන් මිනිසාට බෝ කරන ප්‍රධාන වාහක මදුරු විශේෂය කුමක්ද?", "ඊඩිස් ඊජිප්ටයි සහ ඊඩිස් ඇල්බොපික්ටස්", "ඇනොෆිලිස් මදුරුවා", "කියුලෙක්ස් මදුරුවා", "වැලි මැස්සා", "සුදු ඉරි සහිත ඊඩිස් (Aedes) මදුරුවා දිවා කාලයේදී දෂ්ට කරමින් ඩෙංගු වෛරසය සම්ප්‍රේෂණය කරයි."),
        q("ඩෙංගු රෝග කාරක වෛරසය පවතින ප්‍රධාන සෙරොටයිප් හෙවත් ප්‍රභේද ගණන කීයද?", "ප්‍රභේද 4කි (DEN-1, DEN-2, DEN-3, DEN-4)", "ප්‍රභේද 2කි", "ප්‍රභේද 8කි", "එක් ප්‍රභේදයක් පමණි", "එක් ප්‍රභේදයකට ප්‍රතිශක්තිය ඇති වුවද වෙනත් ප්‍රභේදයකින් නැවත ඩෙංගු වැළඳී රක්තපාත තත්ත්වයට පත්විය හැක."),
        q("ඩෙංගු රෝගියෙකුට උණ හා ඇඟපත වේදනාව සමනය කිරීම සඳහා ලබා නොදිය යුතු ඖෂධ කාණ්ඩය කුමක්ද?", "ඇස්ප්‍රින්, අයිබියුප්‍රොෆෙන් හා ඩයික්ලොෆෙනැක් වැනි NSAIDs ඖෂධ", "පැරසිටමෝල්", "මුඛ සජලන ද්‍රාවණය (ORS)", "කැඳ හා පළතුරු යුෂ", "NSAIDs කාණ්ඩයේ වේදනා නාශක ඩෙංගු රෝගියාගේ ආමාශයික රුධිර වහනය හා රුධිර පට්ටිකා බිඳවැටීම උග්‍ර කරයි."),
        q("ඩෙංගු රක්තපාත උණ (DHF) අවස්ථාවකදී ජීවිතයට දැඩි තර්ජනයක් එල්ල වන ප්‍රධාන ව්‍යාධිජනක තත්ත්වය කුමක්ද?", "රුධිර නාලවලින් ප්ලාස්මා තරලය කාන්දු වී කම්පන තත්ත්වයක් (Dengue Shock) ඇතිවීම", "හිසකෙස් ගැලවී යාම", "දත් දිරාපත් වීම", "ඇසේ සුද ඇතිවීම", "ප්ලාස්මා කාන්දුව නිසා රුධිර පීඩනය ක්ෂණිකව පහත වැටෙන බැවින් නිවැරදි තරල කළමනාකරණය අත්‍යවශ්‍ය වේ."),
        q("ක්ෂය රෝගය (Tuberculosis) ඇති කරන රෝග කාරක බැක්ටීරියාව කුමක්ද?", "මයිකොබැක්ටීරියම් ටියුබර්කියුලෝසිස් (Mycobacterium tuberculosis)", "විබ්‍රියෝ කොලරේ", "සැල්මොනෙල්ලා ටයිෆි", "ප්ලාස්මෝඩියම් වයිවැක්ස්", "ක්ෂය රෝගය ප්‍රධාන වශයෙන් පෙනහලුවලට බලපාන බැක්ටීරියා ආසාදනයකි."),
        q("පෙනහලු ක්ෂය රෝගය හඳුනාගැනීම සඳහා රෝගියෙකු සති දෙකකට වඩා කැස්ස පවතී නම් සිදුකරන මූලික පරීක්ෂණය කුමක්ද?", "සෙම පරීක්ෂණය (Sputum AFB Microscopy)", "මූත්‍රා පරීක්ෂණය", "අක්ෂි පරීක්ෂණය", "ශ්‍රවණ පරීක්ෂණය", "සති 2කට වැඩි කැස්ස, සවස් කාලයේ මද උණ, රාත්‍රී දහඩිය දැමීම හා බර අඩුවීම ඇති විට සෙම පරීක්ෂා කෙරේ."),
        q("ශ්‍රී ලංකාවේ ක්ෂය රෝගීන්ට අඛණ්ඩව මාස 6ක් නොමිලේ ප්‍රතිජීවක ඖෂධ ලබාදෙන ජාත්‍යන්තර ප්‍රතිකාර ක්‍රමය කුමක්ද?", "DOTS ක්‍රමය (Directly Observed Treatment, Short-course)", "ORS ක්‍රමය", "CPR ක්‍රමය", "RICE ක්‍රමය", "ඖෂධ අතරමග නතර කිරීමෙන් ප්‍රතිරෝධී ක්ෂය රෝගය ඇතිවීම වැළැක්වීමට DOTS ක්‍රමය යටතේ අධීක්ෂිත ප්‍රතිකාර කෙරේ."),
        q("මී උණ හෙවත් ලෙප්ටොස්පයිරෝසිස් (Leptospirosis) රෝගය ගොවීන්ට හා පතල්කරුවන්ට ප්‍රධාන වශයෙන් බෝ වන්නේ කෙසේද?", "මීයන්ගේ මූත්‍රා මිශ්‍ර වූ මඩ හා ජලය හරහා සමේ කුඩා තුවාල තුළින් බැක්ටීරියාව ඇතුළු වීමෙන්", "මදුරු දෂ්ටනයෙන්", "මීයන් ඇල්ලීමෙන් පමණි", "වාතයෙන් ආඝ්‍රාණය වීමෙන්", "කුඹුරු හා අපවිත්‍ර ජල මාර්ගවල බැසීමට පෙර ගොවීන්ට MOH මගින් ඩොක්සිසයික්ලින් (Doxycycline) නිවාරණ ඖෂධ ලබාදේ."),
        q("මී උණ රෝගයෙන් ආරක්ෂා වීම සඳහා කුඹුරු වැඩවලට බැසීමට පෙර සෞඛ්‍ය අංශ මගින් ලබාදෙන රෝග නිවාරණ ඖෂධය කුමක්ද?", "ඩොක්සිසයික්ලින් (Doxycycline)", "පැරසිටමෝල්", "මෙට්ෆෝමින්", "ඉන්සියුලින්", "අවදානම් ප්‍රදේශවල ගොවීන් සතියකට වරක් නියමිත මාත්‍රාව ලබාගැනීමෙන් මී උණ වැළැක්විය හැක."),
        q("ජලභීතිකාව (Rabies) රෝග කාරක වෛරසය මිනිසාගේ ශරීරයේ කුමන පද්ධතියට ප්‍රධාන වශයෙන් හානි කරයිද?", "මධ්‍යම ස්නායු පද්ධතියට (මොළය හා සුෂුම්නාව)", "ආහාර ජීර්ණ පද්ධතියට", "අස්ථි පද්ධතියට", "බහිස්ස්‍රාවී පද්ධතියට", "රෝග ලක්ෂණ මතු වූ පසු 100%ක්ම පාහේ මාරාන්තික වන ජලභීතිකාව එන්නත් මගින් සම්පූර්ණයෙන්ම වැළැක්විය හැක."),
        q("බල්ලෙකු හෝ පූසෙකු සපා කෑ විගසම ජලභීතිකාව වැළැක්වීමට නිවසේදී ගත යුතු අතිශය වැදගත් පළමු පියවර කුමක්ද?", "තුවාලය ගලා යන පිරිසිදු ජලයෙන් හා සබන් යොදා අවම වශයෙන් විනාඩි 15ක් හොඳින් සෝදා හැරීම", "තුවාලය මත කෝපි කුඩු හෝ ගොම ආලේප කිරීම", "තුවාලය තදින් වෙළා ගැනීම", "දින කිහිපයක් බලා සිටීම", "විනාඩි 15ක් සබන් හා ගලා යන ජලයෙන් සේදීමෙන් වෛරසයෙන් විශාල කොටසක් සේදී ඉවත් වේ."),
        q("බරවා රෝගය (Lymphatic Filariasis) වැළඳුණු පුද්ගලයෙකුගේ රුධිරයේ මයික්‍රොෆයිලේරියා පරපෝෂිතයන් පරීක්ෂා කිරීම සඳහා රුධිර සාම්පල ලබාගන්නේ කුමන වේලාවේද?", "රාත්‍රී කාලයේදී (රාත්‍රී 8.00 සිට මධ්‍යම රාත්‍රිය දක්වා)", "උදෑසන 7.00ට", "මධ්‍යහ්න 12.00ට", "සවස 3.00ට", "කියුලෙක්ස් මදුරුවා රාත්‍රියේ දෂ්ට කරන බැවින් රාත්‍රී කාලයේදී පමණක් පරපෝෂිතයන් පර්යන්ත රුධිරයට පැමිණේ."),
        q("බරවා රෝගය සම්ප්‍රේෂණය කරන ප්‍රධාන මදුරු විශේෂය කුමක්ද?", "කියුලෙක්ස් මදුරුවා (Culex quinquefasciatus)", "ඊඩිස් මදුරුවා", "ඇනොෆිලිස් මදුරුවා", "ගෙමැස්සා", "කාණු හා අපවිත්‍ර ජලයේ බෝවන කියුලෙක්ස් මදුරුවා වසා ගැටිති හා වසා වාහිනී අවහිර කරන බරවා පණුවා බෝ කරයි."),
        q("මැලේරියාව ඇති කරන ප්ලාස්මෝඩියම් (Plasmodium) පරපෝෂිතයා මිනිසාට බෝ කරන මදුරුවා කවුරුන්ද?", "ගැහැණු ඇනොෆිලිස් මදුරුවා (Female Anopheles)", "පිරිමි ඇනොෆිලිස් මදුරුවා", "ඊඩිස් මදුරුවා", "කියුලෙක්ස් මදුරුවා", "ශ්‍රී ලංකාව WHO මගින් මැලේරියාව තුරන් කළ රටක් ලෙස සහතික කළද විදේශ සංචාරකයන් මගින් නැවත පැමිණීමේ අවදානම පවතී."),
        q("ශ්‍රී ලංකාවේ ජාතික ප්‍රතිශක්තිකරණ වැඩසටහන (EPI) යටතේ අලුත උපන් බිළිඳෙකුට පැය 24ක් ඇතුළත ලබාදෙන පළමු එන්නත කුමක්ද?", "BCG එන්නත (දරුණු ක්ෂය රෝග ආකාරවලින් ආරක්ෂා වීමට)", "MMR එන්නත", "ජපන් එන්සෙෆලයිටිස් එන්නත", "පැපොල එන්නත", "BCG එන්නත උරහිසේ වම් බාහුවේ ඉහළ කොටසේ සම තුළට (Intradermal) ලබාදේ."),
        q("ශ්‍රී ලංකාවේ ළමා ප්‍රතිශක්තිකරණ වැඩසටහන යටතේ මාස 2, 4 සහ 6 යන වයස්වලදී ලබාදෙන පංච සංයුජ (Pentavalent) එන්නතෙන් ආරක්ෂාව සැලසෙන රෝග 5 මොනවාද?", "ගලපටලය, කක්කල් කැස්ස, පිටගැස්ම, හෙපටයිටිස් B සහ හිමොෆිලස් ඉන්ෆ්ලුවෙන්සා B", "ඩෙංගු, මැලේරියාව, බරවා, මී උණ සහ කොළරාව", "සරම්ප, කම්මුල්ගාය, රුබෙල්ලා, පෝලියෝ සහ පැපොල", "දියවැඩියාව, අධි රුධිර පීඩනය, ඇදුම, පිළිකා සහ හෘද රෝග", "තනි එන්නතක් මගින් මාරාන්තික බෝවන රෝග 5කින් දරුවා ආරක්ෂා කිරීම පංච සංයුජ එන්නතේ විශේෂත්වයයි."),
        q("ගැබිණි මවකට රුබෙල්ලා (ජර්මන් සරම්ප) රෝගය වැළඳුණහොත් කුස තුළ සිටින කලලයට ඇතිවිය හැකි බරපතළ ආබාධ මොනවාද?", "සංජානනීය රුබෙල්ලා සින්ඩ්‍රෝමය — බිහිරි බව, අන්ධ බව හා හෘද ආබාධ", "දත් කැක්කුම", "උදරාබාධ", "සමේ සුදු ලප", "එබැවින් සෑම ළමයෙකුටම මාස 9දී සහ අවුරුදු 3දී MMR එන්නත අනිවාර්යයෙන්ම ලබාදෙනු ලැබේ."),
        q("පාසල් වයසේ දරුවන්ට වයස අවුරුදු 11දී (7 ශ්‍රේණියේදී) පාසල් සෞඛ්‍ය වැඩසටහන යටතේ ලබාදෙන එන්නත කුමක්ද?", "aTd එන්නත (වැඩිහිටි පිටගැස්ම හා ගලපටලය බූස්ටර් එන්නත)", "BCG එන්නත", "ජපන් එන්සෙෆලයිටිස් එන්නත", "රොටාවයිරස් එන්නත", "පිටගැස්ම සහ ගලපටලයට එරෙහි ප්‍රතිශක්තිය ජීවිත කාලය පුරාම පවත්වා ගැනීමට මෙම බූස්ටර් මාත්‍රාව ලබාදේ."),
        q("සරම්ප, කම්මුල්ගාය හා රුබෙල්ලා යන වෛරස් රෝග තුනෙන් ආරක්ෂා වීම සඳහා ලබාදෙන ඒකාබද්ධ එන්නත කුමක්ද?", "MMR එන්නත", "DPT එන්නත", "BCG එන්නත", "OPV එන්නත", "MMR එන්නත ශ්‍රී ලංකාවේ මාස 9 සහ අවුරුදු 3 යන වයස්වලදී නොමිලේ ලබාදේ."),
        q("ජපන් එන්සෙෆලයිටිස් (Japanese Encephalitis) වෛරසය මිනිසාට බෝ කරන ප්‍රධාන වාහක මදුරුවා හා අතරමැදි සත්ත්වයා කවුරුන්ද?", "කියුලෙක්ස් මදුරුවා සහ ඌරන් හා ජලජ පක්ෂීන්", "ඊඩිස් මදුරුවා සහ බල්ලන්", "ඇනොෆිලිස් මදුරුවා සහ මීයන්", "ගෙමැස්සා සහ ගවයන්", "සජීවී ජපන් එන්සෙෆලයිටිස් එන්නත දරුවාට වයස අවුරුදු 1 සම්පූර්ණ වූ විට ලබාදේ."),
        q("උණ සන්නිපාතය (Typhoid Fever) සහ කොළරාව (Cholera) යන බැක්ටීරියා රෝග මිනිසාට සම්ප්‍රේෂණය වන ප්‍රධාන මාර්ගය කුමක්ද?", "මලපහ මගින් දූෂිත වූ ජලය හා ආහාර පානය කිරීම (Fecal-oral Route)", "මදුරු දෂ්ටනය", "සම ස්පර්ශය", "රුධිර පාරවිලයනය", "පානීය ජලය හොඳින් උණු කර බීම සහ වැසිකිළි යාමෙන් පසු සබන් ගා අත් සේදීම මෙම රෝග වළකාලයි."),
        q("කොළරා රෝගයේ (Cholera) දරුණුතම හා මාරාන්තික රෝග ලක්ෂණය වන්නේ කුමක්ද?", "හාල් සේදූ වතුර වැනි අධික දියර මලපහ පිටවීම නිසා ක්ෂණික විජලනය ඇතිවීම", "වියළි කැස්ස", "හන්දිපත් රුදාව", "ඇස් කහ වීම", "විබ්‍රියෝ කොලරේ බැක්ටීරියාව නිසා ඇතිවන මෙම තත්ත්වයේදී ක්ෂණිකව ORS සහ ශිරා තරල ලබාදිය යුතුය."),
        q("අතීසාරය හෝ පාචනය වැළඳුණු දරුවෙකුට විජලනය වැළැක්වීම සඳහා නිවසේදීම ලබාදිය යුතු හොඳම ප්‍රතිකාරය කුමක්ද?", "මුඛ සජලන ද්‍රාවණය (ORS / ජීවනී)", "පැණි බීම වර්ග", "කිරි තේ", "තෙල් අධික ආහාර", "ORS මගින් ශරීරයෙන් අහිමි වූ ජලය සහ සෝඩියම්, පොටෑසියම් ලවණ ඉක්මනින් ප්‍රතිස්ථාපනය කෙරේ."),
        q("හෙපටයිටිස් A (Hepatitis A) වෛරස් රෝගයේදී මූලිකවම ආසාදනයට හා ඉදිමීමට ලක්වන අභ්‍යන්තර ඉන්ද්‍රිය කුමක්ද?", "අක්මාව (Liver)", "පෙනහලු", "වකුගඩු", "ආමාශය", "දූෂිත ආහාර හා ජලයෙන් බෝවන හෙපටයිටිස් A හිදී ඇස් හා මූත්‍රා කහ වීම (සෙංගමාලය) දැකිය හැක."),
        q("රෝගියෙකුගේ තුවාලයකට පස් හෝ මළකඩ කෑ ඇණයක් හරහා ඇතුළු වී මාංශ පේශි දැඩි ලෙස සංකෝචනය කරන මාරාන්තික බැක්ටීරියා රෝගය කුමක්ද?", "පිටගැස්ම (Tetanus — Clostridium tetani)", "පැපොල", "සරම්ප", "බරවා", "නිර්වායු බැක්ටීරියාවක් නිසා ඇතිවන පිටගැස්මේදී හකු තදවීම (Lockjaw) සිදුවන අතර එන්නත මගින් වළකාලයි."),
        q("කම්මුල්ගාය (Mumps) රෝගයේදී ඉදිමීමට ලක්වන මිනිස් සිරුරේ ග්‍රන්ථි මොනවාද?", "කන් දෙකට පහළින් පිහිටි කර්ණමූල කේඨ ග්‍රන්ථි (Parotid Salivary Glands)", "තයිරොයිඩ් ග්‍රන්ථිය", "අධිවෘක්ක ග්‍රන්ථිය", "පිටියුටරි ග්‍රන්ථිය", "වෛරස් රෝගයක් වන මෙය කෙළ බිඳිති මගින් බෝ වන අතර ඇතැම් විට පිරිමි දරුවන්ගේ වෘෂණ කෝෂ ඉදිමීමද ඇති කළ හැක."),
        q("පැපොල (Chickenpox) රෝගය ඇති කරන වෛරසය කුමක්ද?", "වැරිසෙල්ලා සොස්ටර් වෛරසය (Varicella Zoster Virus)", "ඉන්ෆ්ලුවෙන්සා වෛරසය", "හෙපටයිටිස් වෛරසය", "රයිනෝ වෛරසය", "උණ සමග සිරුරේ ජල බිබිලි ඇති කරන මෙම රෝගය ශ්වසන බිඳිති හා බිබිලි තරලය මගින් ඉක්මනින් බෝවේ."),
        q("ලාදුරු රෝගය (Leprosy) කල්තියා හඳුනාගැනීමට උපකාරී වන ප්‍රධානතම මූලික රෝග ලක්ෂණය කුමක්ද?", "සමේ ඇතිවන සංවේදනය නොමැති (හිරිවැටුණු) ලා පැහැති හෝ රතු පැහැති ලප", "දැඩි කැස්ස", "උදර වේදනාව", "අධික උණ", "ලාදුරු රෝගය සම්පූර්ණයෙන්ම සුව කළ හැකි බැක්ටීරියා රෝගයක් වන අතර MDT ප්‍රතිකාරය රජයේ රෝහල්වලින් නොමිලේ ලැබේ."),
        q("හිසේ උකුණන්, කුෂ්ඨ රෝග හා ළමුන් අතර සමේ කැසීම ඇති කරන 'කසන රෝගය' (Scabies) බෝ කරන ක්ෂුද්‍ර සත්ත්වයා කවුරුන්ද?", "සාකොප්ටීස් ස්කේබී නම් කුඩා මයිටාවා (Itch Mite)", "බැක්ටීරියාවක්", "වෛරසයක්", "ප්‍රොටොසෝවාවෙක්", "ඇඟිලි කරු හා සමේ නැමිවල රාත්‍රියට අධික කැසීමක් ඇති කරන මෙම රෝගය පවුලේ සියල්ලන්ට එකවර ප්‍රතිකාර කිරීමෙන් සුව වේ."),
        q("දද හා අළුහම් (Ringworm / Pityriasis versicolor) වැනි සමේ රෝග ඇති කරන ක්ෂුද්‍රජීවී කාණ්ඩය කුමක්ද?", "දිලීර (Fungi)", "වෛරස්", "බැක්ටීරියා", "ප්‍රොටොසෝවා", "දහඩිය හා තෙතමනය රැඳෙන ස්ථානවල දිලීර පහසුවෙන් වර්ධනය වන බැවින් සම වියළිව හා පිරිසිදුව තබා ගත යුතුය."),
        q("අක්ෂි පටල ප්‍රදාහය හෙවත් ඇස් රුදාව (Conjunctivitis) රෝගය පාසල් හා නිවාස තුළ පැතිර යාම වැළැක්වීමට ගත යුතු ප්‍රධාන පියවර කුමක්ද?", "රෝගියාගේ ලේන්සු, තුවා හා කොට්ට උර හවුලේ භාවිත නොකිරීම සහ නිතර දෑත් සේදීම", "රෝගියා දෙස බැලීමෙන් වැළකීම", "අඳුරු කාමරයක වසා දැමීම", "උණුසුම් තෙල් ඇසට දැමීම", "ඇස් රුදාව ඇසෙන් ඇස බැලීමෙන් බෝ නොවේ — එය බෝ වන්නේ රෝගියාගේ කඳුළු හා කබ තැවරුණු දෑත් හා රෙදි මගිනි."),
        q("පෝලියෝ (Poliomyelitis) රෝගය මූලිකවම මිනිසාගේ ශරීරයට කරන බරපතළම හානිය කුමක්ද?", "සුෂුම්නාවේ චාලක ස්නායු විනාශ කර පාද හා අත් ස්ථිරවම පණ නැති කිරීම (අංශභාගය)", "ඇස් පෙනීම නැති කිරීම", "සමේ ලප ඇති කිරීම", "රුධිරය කැටි ගැසීම වැළැක්වීම", "මුඛ පෝලියෝ බිංදු (OPV) හා එන්නත (IPV) මගින් ශ්‍රී ලංකාව පෝලියෝ රෝගයෙන් තොර රටක් බවට පත්ව ඇත."),
        q("ක්ෂුද්‍රජීවියෙකු ශරීරයට ඇතුළු වූ මොහොතේ සිට රෝගයේ පළමු රෝග ලක්ෂණ මතු වන තෙක් ගතවන කාල පරාසය හඳුන්වන්නේ කෙසේද?", "බීජෞෂණ සමය හෙවත් ඉන්කියුබේෂන් කාලය (Incubation Period)", "සුවවීමේ කාලය", "නිරෝධායන කාලය", "රෝග නිවාරණ කාලය", "සෑම බෝවන රෝගයකටම ආවේණික බීජෞෂණ සමයක් ඇති අතර එම කාලයේදී පවා ඇතැම් රෝග අන් අයට බෝවිය හැක."),
        q("කිසිදු රෝග ලක්ෂණයක් නොපෙන්වන නමුත් තම සිරුර තුළ රෝග කාරකයන් දරාගෙන අන් අයට රෝගය පතුරුවන පුද්ගලයා කවුරුන්ද?", "රෝග වාහකයා (Asymptomatic Carrier)", "රෝග නිවාරකයා", "ප්‍රතිශක්තිකරුවා", "ඖෂධවේදියා", "උණ සන්නිපාතය හා කොවිඩ්-19 වැනි රෝගවලදී රෝග ලක්ෂණ නොපෙන්වන වාහකයන් හරහා රෝගය වේගයෙන් පැතිරේ."),
        q("රෝගයක් වැළඳුණු බව තහවුරු වූ පුද්ගලයෙකු අන් නිරෝගී අයට බෝවීම වැළැක්වීමට වෙනම රඳවා තැබීම කුමක්ද?", "හුදකලා කිරීම (Isolation)", "නිරෝධායනය", "එන්නත්කරණය", "පුනරුත්ථාපනය", "රෝගී වූ අය වෙන් කිරීම Isolation වන අතර රෝගියෙකුට නිරාවරණය වූ නිරෝගී සැකකටයුතු අය වෙන් කිරීම Quarantine වේ."),
        q("බෝවන රෝගයක් ඇති අයෙකුගේ ආශ්‍රිතයෙකු වූ නිරෝගී පුද්ගලයෙකු රෝග ලක්ෂණ මතු වේදැයි බැලීමට බීජෞෂණ සමය තුළ වෙන් කර තැබීම කුමක්ද?", "නිරෝධායනය (Quarantine)", "හුදකලා කිරීම", "විෂහරණය", "සජලනය", "වසංගත රෝග පැතිරීම පාලනය කිරීමේදී නිරෝධායන නීති අනුගමනය කිරීම මහජන ආරක්ෂාවට වැදගත් වේ."),
        q("ප්‍රජාවක බහුතර පිරිසකට එන්නත් මගින් ප්‍රතිශක්තිය ලබාදීම නිසා එන්නත් ලබා නොගත් දුර්වල පුද්ගලයන්ටද රෝගය පැතිරීම වැළකීම කුමක්ද?", "සමූහ ප්‍රතිශක්තිය (Herd Immunity)", "ස්වාභාවික මරණය", "ආසාත්මිකතාව", "ව්‍යාප්තිය", "ඉහළ එන්නත් ආවරණයක් පවත්වා ගැනීමෙන් ළදරුවන් හා ප්‍රතිශක්තිය හීන අය වසංගතවලින් ආරක්ෂා වේ."),
        q("එන්නත් නිෂ්පාදිත ස්ථානයේ සිට දරුවාට ලබාදෙන මොහොත දක්වා නියමිත සිසිල් උෂ්ණත්වය (+2°C සිට +8°C) පවත්වා ගැනීමේ පද්ධතිය කුමක්ද?", "ශීත දාමය (Cold Chain)", "සැපයුම් ජාලය", "උෂ්ණත්ව මානය", "විෂබීජහරණ ක්‍රියාවලිය", "ශීත දාමය බිඳ වැටුණහොත් එන්නත්වල සක්‍රීයභාවය විනාශ වී ප්‍රතිශක්තිය ඇති නොවේ."),
        q("ප්‍රතිශක්තිකරණ ක්‍රියාවලියේදී මව්කිරි මගින් සහ වැදෑමහ හරහා මවගෙන් දරුවාට ස්වාභාවිකව ලැබෙන ප්‍රතිදේහ මගින් ඇතිවන ප්‍රතිශක්තිය කුමක්ද?", "ස්වාභාවික අක්‍රීය ප්‍රතිශක්තිය (Natural Passive Immunity)", "කෘත්‍රිම සක්‍රීය ප්‍රතිශක්තිය", "ස්වාභාවික සක්‍රීය ප්‍රතිශක්තිය", "කෘත්‍රිම අක්‍රීය ප්‍රතිශක්තිය", "මවගේ ප්‍රතිදේහ දරුවාට ලැබීමෙන් උපතේ මුල් මාස කිහිපයේදී බොහෝ රෝගවලින් දරුවා ස්වාභාවිකව රැකේ."),
        q("රෝගියෙකුගේ මානසික පීඩනයක් හෝ හෘද රෝගයක් නොවන, වෛරස් හෝ බැක්ටීරියා ආසාදනයෙන් පෙනහලු වායු කෝෂවල සැරව පිරී ඇතිවන රෝගය කුමක්ද?", "නියුමෝනියාව (Pneumonia)", "සිරෝසිස්", "දියවැඩියාව", "ඔස්ටියෝපොරෝසිස්", "කුඩා දරුවන් හා වැඩිහිටියන් අතර වේගවත් හුස්ම ගැනීම හා පපුව ඇතුළට ඇදීම නියුමෝනියාවේ අනතුරුදායක ලක්ෂණ වේ."),
        q("කැස්ස හෝ කිවිසුම් යන විට ශ්වසන බිඳිති පැතිරීම වැළැක්වීම සඳහා අනුගමනය කළ යුතු නිවැරදි සෞඛ්‍ය පුරුද්ද (Cough Etiquette) කුමක්ද?", "වැළමිටේ ඇතුළත නැමියට හෝ ටිෂූ කඩදාසියකට කැස්ස/කිවිසුම් යැවීම හා අත් සේදීම", "අත්ලට කැස්ස යවා අන් අය සමග අතට අත දීම", "මුහුණ ආවරණය නොකර විවෘතව කිවිසුම් යැවීම", "පොදු ස්ථානවල කෙළ ගැසීම", "අත්ලට කැස්ස යැවීමෙන් දොර අගුලු හා මේස මත විෂබීජ තැවරෙන බැවින් වැළමිට භාවිතය ආරක්ෂිත වේ."),
        q("ඩෙංගු මදුරුවන් බෝවන ස්ථාන විනාශ කිරීම සඳහා ශ්‍රී ලංකාවේ සෑම නිවසක්ම හා පාසලක්ම අවම වශයෙන් සතියකට කොපමණ කාලයක් පරිසරය පරීක්ෂා කළ යුතුද?", "සතියකට විනාඩි 30ක් පමණ (ඩෙංගු මර්දන පැය භාගය)", "වසරකට එක් දිනක් පමණි", "මාස 6කට වරක්", "පැය 12ක් අඛණ්ඩව", "ඊඩිස් මදුරු බිත්තර දින 7-10ක් ඇතුළත සම්පූර්ණ මදුරුවෙකු වන බැවින් සතිපතා විනාඩි 30 පරීක්ෂාව ජීවන චක්‍රය බිඳ දමයි."),
        q("ඩෙංගු මදුරු කීටයන් ජල ටැංකි හා පොකුණුවල බෝවීම පාලනය කිරීමට යොදාගන්නා ස්වාභාවික ජීව විද්‍යාත්මක පාලන ක්‍රමය (Biological Control) කුමක්ද?", "ගප්පි (Poecilia reticulata) හා දණ්ඩි වැනි කීට භක්ෂක මත්ස්‍යයන් ඇති කිරීම", "මෝටර් තෙල් වත් කිරීම", "බ්ලීචින් පවුඩර් දැමීම", "ජලය සම්පූර්ණයෙන් හිස් නොකර තැබීම", "ජීව විද්‍යාත්මක පාලනය රසායනික දූෂණයෙන් තොර පරිසර හිතකාමී මදුරු මර්දන ක්‍රමයකි."),
        q("මැස්සන් මගින් ප්‍රධාන වශයෙන්ම ව්‍යාප්ත වන ආහාර හා ජලය ආශ්‍රිත බෝවන රෝග කාණ්ඩය කුමක්ද?", "පාචනය, උණ සන්නිපාතය සහ අතීසාරය", "ඩෙංගු සහ බරවා", "ඒඩ්ස් සහ හෙපටයිටිස් B", "මී උණ සහ ජලභීතිකාව", "ගෙමැස්සන් මලපහ හා කුණු කසළ මත වසා පසුව විවෘත ආහාර මත වැසීමෙන් පාදවල ඇලී ඇති රෝග කාරක තැන්පත් කරයි."),
        q("රෝහල්වලදී හා අනෙකුත් ස්ථානවලදී ආසාදිත රුධිරය තැවරුණු එන්නත් කටු හවුලේ භාවිත කිරීමෙන් බෝවිය හැකි බරපතළ වෛරස් රෝග දෙක කුමක්ද?", "HIV/AIDS සහ හෙපටයිටිස් B හා C", "පැපොල සහ සරම්ප", "ඩෙංගු සහ මැලේරියාව", "කොළරාව සහ උණ සන්නිපාතය", "එක් වරක් පමණක් භාවිත කර ඉවත දමන ඉවතලන සිරින්ජ (Disposable Syringes) භාවිතය මෙය වළක්වයි."),
        q("සෑම පුද්ගලයෙකුම සෞඛ්‍යාරක්ෂිතව අත් සේදීමේදී (Hand Washing with Soap) අවම වශයෙන් සබන් පෙන නංවා ඇතිල්ලිය යුතු කාලය කොපමණද?", "තත්පර 20ක්වත් හොඳින් සේදිය යුතුය", "තත්පර 2ක් පමණි", "විනාඩි 10ක්", "ජලයෙන් පමණක් තෙමීම", "අත්ල, පිටිඅල්ල, ඇඟිලි කරු, මහපටැඟිල්ල හා නිය අග පියවර අනුගමනය කරමින් තත්පර 20ක් සේදීමෙන් විෂබීජ විනාශ වේ."),
        q("ප්‍රජාතන්ත්‍රවාදී හා පිරිසිදු පාසල් පරිසරයක් පවත්වා ගැනීමට පළාතේ මහජන සෞඛ්‍ය කටයුතු මෙහෙයවන ප්‍රාදේශීය වෛද්‍ය ආයතනය කුමක්ද?", "සෞඛ්‍ය වෛද්‍ය නිලධාරී කාර්යාලය (MOH — Medical Officer of Health)", "ප්‍රාදේශීය ලේකම් කාර්යාලය පමණි", "පොලිස් ස්ථානය", "තැපැල් කාර්යාලය", "රෝග නිවාරණය, මාතෘ හා ළමා සායන, එන්නත්කරණය හා පාරිසරික සෞඛ්‍යය MOH කාර්යාලය මගින් ඉටු කෙරේ."),
        q("ආහාර අලෙවි කරන ආපනශාලා හා හෝටල් පරීක්ෂා කිරීමටත් බෝවන රෝග පාලනය කිරීමටත් ක්ෂේත්‍රයේ කටයුතු කරන නිලධාරියා කවුරුන්ද?", "මහජන සෞඛ්‍ය පරීක්ෂක (PHI — Public Health Inspector)", "පවුල් සෞඛ්‍ය සේවා නිලධාරිනී", "ග්‍රාම නිලධාරී", "විදුහල්පති", "ආහාර සනීපාරක්ෂාව, පානීය ජල පරීක්ෂාව සහ ඩෙංගු පරීක්ෂාවන්හිදී PHI මහතාට නීතිමය බලතල හිමිය."),
        q("ගැබිණි මව්වරුන්ගේ හා අවුරුදු 5ට අඩු දරුවන්ගේ නිවාස වෙත පැමිණ සෞඛ්‍ය හා පෝෂණ උපදෙස් ලබාදෙන නිලධාරිනිය කවුරුන්ද?", "පවුල් සෞඛ්‍ය සේවා නිලධාරිනී (PHM / Public Health Midwife)", "මහජන සෞඛ්‍ය පරීක්ෂක", "සමෘද්ධි නිලධාරී", "වෛද්‍ය අධිකාරී", "ශ්‍රී ලංකාවේ මාතෘ හා ළදරු මරණ අනුපාතය කලාපයේ අවම මට්ටමක තබා ගැනීමට PHM සේවාව අතිමහත් දායකත්වයක් දක්වයි."),
        q("ක්ෂුද්‍ර පණු රෝග (වටපණු හා කොකුපණු) දරුවන් අතර ඇතිවීම වැළැක්වීමට ගත යුතු හොඳම වැළැක්වීමේ පියවර මොනවාද?", "සපත්තු පැළඳීම, නියපොතු කොටට කැපීම, නිතිපතා වැසිකිළි භාවිතය සහ පණු බෙහෙත් ලබාගැනීම", "සැමදා පාවහන් නොමැතිව ඇවිදීම", "එළිමහනේ මලපහ කිරීම", "අමු මස් අනුභවය", "කොකුපණු කීටයන් පාවහන් නොමැති පාදයේ සම විදගෙන ඇතුළු වී දරුණු රක්තහීනතාව ඇති කරයි."),
        q("යම් බෝවන රෝගයක් නිශ්චිත භූගෝලීය ප්‍රදේශයක සාමාන්‍යයෙන් අපේක්ෂිත මට්ටමකින් නිරන්තරයෙන් පැවතීම හඳුන්වන්නේ කෙසේද?", "ආවේණික තත්ත්වය (Endemic)", "වසංගත තත්ත්වය (Epidemic)", "ගෝලීය වසංගතය (Pandemic)", "අහඹු තත්ත්වය (Sporadic)", "උදාහරණයක් ලෙස නිවර්තන රටවල ඩෙංගු රෝගය වසර පුරාම පැවතීම ආවේණික තත්ත්වයකි."),
        q("කෙටි කාලයක් තුළ කිසියම් ප්‍රජාවක අපේක්ෂිත ප්‍රමාණයට වඩා අසාමාන්‍ය ලෙස වැඩි පිරිසකට එක්වරම බෝවන රෝගයක් පැතිර යාම කුමක්ද?", "වසංගත තත්ත්වය (Epidemic)", "ආවේණික තත්ත්වය", "ප්‍රතිශක්තිය", "සමූහ ආරක්ෂාව", "වැසි සමයෙන් පසු ඩෙංගු හෝ මී උණ රෝගීන් සංඛ්‍යාව එක්වරම ඉහළ යාම වසංගත තත්ත්වයකට උදාහරණයකි."),
        q("රටවල් හා මහාද්වීප ගණනාවක් පුරා ලෝක ව්‍යාප්තව වේගයෙන් පැතිර යන මහා වසංගත තත්ත්වය හඳුන්වන්නේ කෙසේද?", "ගෝලීය වසංගතය හෙවත් පැන්ඩමික් (Pandemic)", "ආවේණික රෝගය", "අහඹු රෝගය", "පාරම්පරික රෝගය", "2020 වසරේ ඇති වූ COVID-19 වසංගතය මුළු ලොවම වෙලාගත් Pandemic තත්ත්වයකට ආසන්නතම උදාහරණයයි."),
        q("සතුන්ගෙන් මිනිසුන්ට ස්වාභාවිකව සම්ප්‍රේෂණය වන ජලභීතිකාව හා මී උණ වැනි රෝග හඳුන්වන පොදු විද්‍යාත්මක නාමය කුමක්ද?", "සත්ත්ව-මනුෂ්‍ය රෝග හෙවත් සූනෝසිස් (Zoonotic Diseases)", "ජානමය රෝග", "පෝෂණ ඌනතා රෝග", "අසාත්මිකතා", "මිනිසා සහ සතුන් අතර හුවමාරු වන රෝග පාලනයට සුරතල් සතුන් එන්නත් කිරීම අත්‍යවශ්‍ය වේ."),
        q("වසරකට වරක් නිවසේ සුරතල් බල්ලන්ට හා බළලුන්ට ජලභීතිකා එන්නත ලබාදීම වැදගත් වන්නේ ඇයි?", "සතුන් තුළ වෛරසය පැතිරීම වැළැක්වීමෙන් මිනිසුන්ට ජලභීතිකාව බෝවීම මුලින්ම නතර කළ හැකි බැවින්", "සතුන්ගේ උස වැඩි කිරීමට", "ලොම් පැහැපත් කිරීමට", "බිරීම නතර කිරීමට", "විශේෂයෙන් මාස 3ට වැඩි සුනඛ පැටවුන්ට පළමු එන්නත ලබාදී වාර්ෂිකව බූස්ටර් එන්නත දිය යුතුය."),
        q("සැකකටයුතු නිරෝගී සුනඛයෙකු මිනිසෙකු සපා කෑ පසු ජලභීතිකා අවදානම තහවුරු කර ගැනීමට එම සුනඛයා කොපමණ දින ගණනක් නිරීක්ෂණය කළ යුතුද?", "දින 10-14ක් නිරීක්ෂණය කළ යුතුය", "දින 2ක් පමණි", "මාස 6ක්", "වසරක්", "දින 14ක් ගත වන තුරුත් සුනඛයා නිරෝගීව සිටී නම් සපා කෑ මොහොතේ ඔහුගේ ඛේටයේ ජලභීතිකා වෛරසය නොතිබුණු බව තහවුරු වේ."),
        q("ඩෙංගු උණ වැළඳුණු රෝගියෙකුගේ උණ බැස යන අවස්ථාවේදී පවා වහාම රෝහල් ගත කළ යුතු 'අනතුරු ඇඟවීමේ ලක්ෂණ' (Warning Signs) මොනවාද?", "දැඩි උදර වේදනාව, නොනවතින වමනය, විදුරුමස් හෝ නාසයෙන් රුධිරය ගැලීම සහ අධික නිදිමත ගතිය", "ආහාර රුචිය වැඩිවීම", "උණ බැස සුවපත්ව සෙල්ලම් කිරීම", "සාමාන්‍ය මූත්‍රා පිටවීම", "උණ බැස යන 3-5 වන දිනවලදී ප්ලාස්මා කාන්දුව ආරම්භ විය හැකි බැවින් මෙම අනතුරු ලක්ෂණ ගැන අවධානයෙන් සිටිය යුතුය."),
        q("ඩෙංගු රෝගයෙන් සැක කෙරෙන අයෙකුට නිවසේදී ලබාදෙන උණ පාලන ඖෂධය සහ තරල පිළිබඳ නිවැරදි උපදෙස කුමක්ද?", "නියමිත මාත්‍රාවෙන් පැරසිටමෝල් පමණක් ලබාදීම සහ ජීවනී, තැඹිලි, කැඳ වැනි පැහැදිලි තරල බහුලව දීම", "රතු පැහැති කෝලා හා කෝපි දීම", "දිගින් දිගටම ඇස්ප්‍රින් දීම", "ජලය පානය සම්පූර්ණයෙන් නතර කිරීම", "රතු හෝ දුඹුරු පැහැති බීම දීමෙන් රෝගියා වමනය කළහොත් එය රුධිර වමනයදැයි හඳුනාගැනීමට අපහසු වේ."),
        q("රෝගියාට දුර්වල හෝ අක්‍රීය කළ ක්ෂුද්‍රජීවීන් ශරීරගත කර ශරීරය තුළම ප්‍රතිදේහ නිපදවීමට සැලැස්වීම මගින් ලැබෙන ප්‍රතිශක්තිය කුමක්ද?", "කෘත්‍රිම සක්‍රීය ප්‍රතිශක්තිය (Artificial Active Immunity — එන්නත්කරණය)", "ස්වාභාවික අක්‍රීය ප්‍රතිශක්තිය", "කෘත්‍රිම අක්‍රීය ප්‍රතිශක්තිය", "සහජ ප්‍රතිශක්තිය", "එන්නත් මගින් මතක සෛල නිපදවෙන බැවින් දීර්ඝකාලීන රෝග ආරක්ෂාවක් හිමිවේ."),
        q("සර්පයෙකු දෂ්ට කළ පසු හෝ පිටගැස්ම අවදානමකදී ශරීරයට සෘජුවම සූදානම් කළ ප්‍රතිදේහ (Anti-toxin / Immunoglobulin) එන්නත් කිරීම කුමක්ද?", "කෘත්‍රිම අක්‍රීය ප්‍රතිශක්තිය (Artificial Passive Immunity)", "කෘත්‍රිම සක්‍රීය ප්‍රතිශක්තිය", "ස්වාභාවික සක්‍රීය ප්‍රතිශක්තිය", "සමූහ ප්‍රතිශක්තිය", "හදිසි අවස්ථාවලදී ශරීරය ප්‍රතිදේහ නිපදවන තෙක් බලා නොසිට ක්ෂණික ආරක්ෂාව සැපයීමට මෙය යොදාගනී."),
        q("වරක් සරම්ප හෝ පැපොල රෝගය වැළඳී සුව වූ පුද්ගලයෙකුට නැවත එම රෝගය නොවැළඳීමට හේතුවන ප්‍රතිශක්ති වර්ගය කුමක්ද?", "ස්වාභාවික සක්‍රීය ප්‍රතිශක්තිය (Natural Active Immunity)", "කෘත්‍රිම අක්‍රීය ප්‍රතිශක්තිය", "ස්වාභාවික අක්‍රීය ප්‍රතිශක්තිය", "රසායනික ප්‍රතිශක්තිය", "සැබෑ ආසාදනයෙන් පසු ශරීරයේ ප්‍රතිශක්තිකරණ පද්ධතිය තුළ දීර්ඝකාලීන මතක B හා T සෛල ගොඩනැගේ."),
        q("සජීවී එහෙත් දුර්වල කළ රෝග කාරක (Live Attenuated Vaccines) භාවිත කර නිපදවා ඇති එන්නත් වර්ග මොනවාද?", "BCG, MMR සහ මුඛ පෝලියෝ (OPV) එන්නත්", "ටොක්සොයිඩ් පමණි", "මැරූ බැක්ටීරියා පමණි", "ප්‍රතිජීවක පෙති", "සජීවී දුර්වල කළ එන්නත් ඉතා ප්‍රබල හා දීර්ඝකාලීන ප්‍රතිශක්තියක් ලබාදීමට සමත් වේ."),
        q("පිටගැස්ම (Tetanus) සහ ගලපටලය (Diphtheria) සඳහා එන්නත් නිපදවීමේදී බැක්ටීරියා මගින් නිකුත් කරන විෂ අක්‍රීය කර සාදන එන්නත් වර්ගය කුමක්ද?", "ටොක්සොයිඩ් එන්නත් (Toxoids)", "සජීවී වෛරස් එන්නත්", "දිලීර නාශක", "වේදනා නාශක", "ටොක්සොයිඩ් එන්නත් රෝග කාරක බැක්ටීරියාව නිපදවන මාරාන්තික විෂ උදාසීන කිරීමට ප්‍රතිදේහ සාදයි."),
        q("ශ්‍රී ලංකාවේ ගැහැණු දරුවන්ට ගැබ්ගෙල පිළිකාව (Cervical Cancer) ඇති කරන HPV වෛරසයෙන් ආරක්ෂා වීමට ජාතික ප්‍රතිශක්තිකරණ වැඩසටහන යටතේ එන්නත ලබාදෙන්නේ කුමන ශ්‍රේණියේදීද?", "6 ශ්‍රේණියේදී (වයස අවුරුදු 10-11 සම්පූර්ණ වූ විට)", "1 ශ්‍රේණියේදී", "13 ශ්‍රේණියේදී", "වයස අවුරුදු 30දී", "HPV එන්නත මාත්‍රා 2ක් ලෙස මාස 6ක පරතරයකින් පාසල් මට්ටමින් නොමිලේ ලබාදීමෙන් ගැබ්ගෙල පිළිකා වළකාලයි."),
        q("ළමුන්ට සරම්ප (Measles) රෝගය වැළඳුණු විට ඇස් අන්ධ වීම හා සංකූලතා වැළැක්වීම සඳහා වෛද්‍යවරුන් විසින් ලබාදෙන විටමින් වර්ගය කුමක්ද?", "විටමින් A අධි මාත්‍රාව", "විටමින් K", "විටමින් B12", "විටමින් D පමණි", "සරම්ප ආසාදනයේදී ශරීරයේ විටමින් A සංචිත ක්ෂණිකව පහත වැටෙන බැවින් අන්ධතාව වැළැක්වීමට එය ලබාදේ."),
        q("කක්කල් කැස්ස (Pertussis / Whooping Cough) රෝගය පිළිබඳ නිවැරදි හඳුනාගැනීමේ ලක්ෂණය කුමක්ද?", "එක දිගට පවතින දරුණු කැස්ස අවසානයේ හුස්ම ඇදීමේදී ඇසෙන 'හූප්' (Whoop) ශබ්දය සහ වමනය", "පාද ඉදිමීම", "සමේ සුදු පැල්ලම්", "ඇස් කහ වීම", "කුඩා බිළිඳුන්ට ඉතා භයානක විය හැකි කක්කල් කැස්ස පංච සංයුජ එන්නතින් වළකාලයි."),
        q("ගලපටලය (Diphtheria) රෝගයේදී රෝගියාගේ උගුරේ හටගන්නා භයානක තත්ත්වය කුමක්ද?", "උගුරේ ඝන අළු පැහැති පටලයක් සෑදී ශ්වසන මාර්ගය අවහිර වීම", "දිවේ රස නොදැනීම පමණි", "දත් වැටීම", "කන් ඇසීම වැඩිවීම", "වසංගතයක් විය හැකි ගලපටලය ප්‍රතිශක්තිකරණ එන්නත්කරණය හේතුවෙන් ශ්‍රී ලංකාවේ ඉතා දුර්ලභ වී ඇත."),
        q("ලෝක සෞඛ්‍ය සංවිධානය (WHO) විසින් ශ්‍රී ලංකාව මැලේරියාව තුරන් කළ රටක් ලෙස නිල වශයෙන් සහතික කරන ලද්දේ කුමන වසරේදීද?", "2016 වසරේදී", "1985 වසරේදී", "2000 වසරේදී", "2024 වසරේදී", "නිවැරදි නිරීක්ෂණ, ප්‍රතිකාර හා මදුරු පාලන වැඩසටහන් නිසා ශ්‍රී ලංකාව මෙම ඓතිහාසික සෞඛ්‍ය ජයග්‍රහණය ලැබීය."),
        q("බරවා රෝගය (Filariasis) සම්පූර්ණයෙන්ම තුරන් කිරීම සඳහා මහජනතාවට වසරකට වරක් සාමූහිකව ලබාදෙනු ලැබූ ඖෂධය කුමක්ද?", "DEC (Diethylcarbamazine) සහ ඇල්බෙන්ඩසෝල් (Albendazole)", "පැරසිටමෝල්", "ඇස්ප්‍රින්", "ඉන්සියුලින්", "රුධිරයේ සිටින මයික්‍රොෆයිලේරියා කීටයන් විනාශ කිරීමෙන් මදුරුවන්ට රෝගය බෝ වීමේ චක්‍රය නතර විය."),
        q("වාහක මදුරුවන් පාලනය කිරීමේදී මදුරු දැල් භාවිතය, කවුළුවලට දැල් ගැසීම සහ ඩෙංගු බෝවන ටින් කබල් ඉවත් කිරීම අයත් වන්නේ කුමන පාලන ක්‍රමයටද?", "පාරිසරික හා යාන්ත්‍රික පාලන ක්‍රම (Environmental & Mechanical Control)", "ජීව විද්‍යාත්මක පාලනය", "රසායනික පාලනය", "ප්‍රතිශක්තිකරණය", "විෂ රසායනික ද්‍රව්‍ය පරිසරයට මුදා නොහැර මදුරු ගහනය අඩු කිරීමේ වඩාත්ම තිරසාර ක්‍රමය මෙයයි."),
        q("මදුරු කීටයන් විනාශ කිරීමට ජලය මතුපිට ඇබේට් (Temephos) ඉසීම හෝ වැඩිහිටි මදුරුවන් සඳහා දුම් ගැසීම (Fogging) අයත් වන්නේ කුමන ක්‍රමයටද?", "රසායනික පාලන ක්‍රමය (Chemical Control)", "ජීව විද්‍යාත්මක පාලනය", "යාන්ත්‍රික පාලනය", "අධ්‍යාපනික පාලනය", "රසායනික දුම් ගැසීම හදිසි ඩෙංගු වසංගත අවස්ථාවලදී වෛරසය දරන වැඩිහිටි මදුරුවන් ක්ෂණිකව මැරීමට පමණක් යොදාගනී."),
        q("ශල්‍යාගාර උපකරණ සහ රෝගීන්ට භාවිත කළ ඉඳිකටු ආදියෙන් බීජාණු ඇතුළු සියලුම ක්ෂුද්‍රජීවීන් සම්පූර්ණයෙන්ම විනාශ කිරීමේ ක්‍රියාවලිය කුමක්ද?", "ජීවාණුහරණය (Sterilization)", "විෂබීජනාශනය", "සබන් ගා සේදීම", "පෙරීම", "අධික පීඩනය හා තාපය යටතේ හුමාලය (Autoclave) භාවිතයෙන් ජීවාණුහරණය සිදුකෙරේ."),
        q("ගෙබිම, වැසිකිළි සහ මේස මතුපිට ඇති රෝග කාරක ක්ෂුද්‍රජීවීන් විනාශ කිරීම සඳහා රසායනික ද්‍රව්‍ය (Disinfectants) යෙදීම හඳුන්වන්නේ කෙසේද?", "විෂබීජනාශනය (Disinfection)", "ජීවාණුහරණය", "ප්‍රතිශක්තිකරණය", "පැස්චරීකරණය", "විෂබීජනාශක ද්‍රව්‍ය අජීවී මතුපිට සඳහා භාවිත කරන අතර සජීවී සම මත යොදන මෘදු විෂබීජ නාශක Antiseptics නම් වේ."),
        q("කිරි වැනි දියර ආහාරවල පෝෂණ ගුණය හා රසය විනාශ නොවන සේ රෝග කාරක බැක්ටීරියා පමණක් විනාශ කිරීමට යොදාගන්නා තාප ක්‍රමය කුමක්ද?", "පැස්චරීකරණය (Pasteurization)", "ජීවාණුහරණය", "හිමායනය", "වියළීම", "ලුවී පැස්චර් හඳුන්වා දුන් මෙම ක්‍රමයේදී කිරි සෙල්සියස් අංශක 72දී තත්පර 15ක් රත් කර ක්ෂණිකව සිසිල් කරයි."),
        q("රෝගියෙකුගේ තුවාලයක් සේදීමට හෝ ශල්‍යකර්මයකට පෙර සම පිරිසිදු කිරීමට සජීවී පටක මත යොදන රසායනික ද්‍රව්‍ය හඳුන්වන්නේ කෙසේද?", "ප්‍රතිපූතික හෙවත් ඇන්ටිසෙප්ටික් (Antiseptics — උදා පොවිඩෝන් අයඩින්, සර්ජිකල් ස්පිරිට්)", "ප්‍රබල ඇසිඩ් වර්ග", "කෘමිනාශක", "බ්ලීචින් කුඩු", "ඇන්ටිසෙප්ටික් ද්‍රව්‍ය සජීවී සෛලවලට හානි නොකර මතුපිට බැක්ටීරියා පාලනය කරයි."),
        q("හෙපටයිටිස් B (Hepatitis B) වෛරසය මිනිසාගෙන් මිනිසාට බෝවන ප්‍රධාන මාර්ගයක් නොවන්නේ පහත සඳහන් කුමක්ද?", "රෝගියා සමග අතට අත දීම හෝ එකට වාඩි වී ආහාර ගැනීම", "ආසාදිත රුධිර පාරවිලයනය", "අනාරක්ෂිත ලිංගික සබඳතා", "ජීවාණුහරණය නොකළ පච්චා කෙටීමේ ඉඳිකටු", "හෙපටයිටිස් B හා HIV සාමාන්‍ය සමාජ ඇසුරෙන් හෝ එකට ආහාර ගැනීමෙන් බෝ නොවේ."),
        q("හදිසි පාචන තත්ත්වයකදී කුඩා දරුවෙකු තුළ දැඩි විජලනය (Severe Dehydration) ඇති බව හඳුනාගන්නා අනතුරුදායක සලකුණු මොනවාද?", "ගිලුණු ඇස්, අධික උදාසීන බව හෝ සිහිසුන් ගතිය, මූත්‍රා පිට නොවීම සහ සම ඇද්ද විට ඉතා සෙමින් ආපසු යාම", "දරුවා සිනාසෙමින් සෙල්ලම් කිරීම", "සාමාන්‍ය දහඩිය දැමීම", "දරුවා උද්යෝගයෙන් ජලය බීම", "දරුණු විජලන ලක්ෂණ දුටු විගස ප්‍රමාද නොවී රෝහලකට ඇතුළත් කර ශිරා තරල ලබාදිය යුතුය."),
        q("මස්, මාළු හා බිත්තර වැනි අමු ආහාර කැපීමට භාවිත කළ පිහිය සහ ලෑල්ල නොසෝදා අමු සලාද එළවළු කැපීමෙන් සිදුවන ආහාර දූෂණය කුමක්ද?", "හරස් දූෂණය (Cross-contamination)", "පැස්චරීකරණය", "පෝෂණ සංරක්ෂණය", "ප්‍රතිචක්‍රීකරණය", "සැල්මොනෙල්ලා වැනි බැක්ටීරියා අමු මස්වලින් නොපිසූ සලාදවලට මාරු වීම වැළැක්වීමට වෙනම කැපුම් ලෑලි භාවිත කළ යුතුය."),
        q("මහජන සෞඛ්‍යය ආරක්ෂා කිරීම සඳහා ශ්‍රී ලංකාවේ පාසල් ළමුන්ට 1, 4 සහ 7 ශ්‍රේණිවලදී පාසල තුළදීම සිදුකරන සෞඛ්‍ය සේවාව කුමක්ද?", "පාසල් වෛද්‍ය පරීක්ෂණය (School Medical Inspection — SMI)", "විභාග ප්‍රතිඵල පරීක්ෂාව", "ක්‍රීඩා තේරීම් පරීක්ෂණය", "වාර්ෂික ත්‍යාග ප්‍රදානය", "MOH කණ්ඩායම මගින් සිසුන්ගේ පෙනීම, ශ්‍රවණය, දත්, පෝෂණය හා එන්නත් තත්ත්වය මෙහිදී පරීක්ෂා කර ප්‍රතිකාර සඳහා යොමු කෙරේ."),
        q("දත් දිරාපත් වීම (Dental Caries) වැළැක්වීමටත් දන්ත එනමලය ශක්තිමත් කිරීමටත් දන්තාලේපවල අඩංගු කළ යුතු අත්‍යවශ්‍ය ඛනිජ සංයෝගය කුමක්ද?", "ෆ්ලෝරයිඩ් (Fluoride)", "සෝඩියම් ක්ලෝරයිඩ්", "යකඩ", "සල්ෆර්", "දිනපතා උදෑසන සහ රාත්‍රී නින්දට පෙර ෆ්ලෝරයිඩ් දන්තාලේපයකින් මිනිත්තු 2ක් දත් මැදීම දත් රෝග වළකාලයි."),
        q("උණ සන්නිපාත රෝගය හඳුනාගැනීමට සිදුකරන වෛද්‍ය රසායනාගාර පරීක්ෂණයක් වන්නේ කුමක්ද?", "රුධිර රෝපණය (Blood Culture) හා වයිඩාල් පරීක්ෂණය (Widal Test)", "සෙම AFB පරීක්ෂණය", "රාත්‍රී රුධිර පටල පරීක්ෂාව", "HbA1c පරීක්ෂණය", "පිරිසිදු නොකළ වීදි ආහාර සහ අයිස් ක්‍රීම් වර්ග මගින් උණ සන්නිපාතය බහුලව පැතිරේ."),
        q("ශ්‍රී ලංකාවේ ප්‍රජා සෞඛ්‍ය සේවාව තුළ 'සංවේදී හා අලුත උපන් බිළිඳාගේ රැකවරණය' සඳහා පවුල් සෞඛ්‍ය සේවා නිලධාරිනිය නිවසට පැමිණෙන්නේ උපතින් කොපමණ දින ගණනක් ඇතුළතද?", "මුල් දින 10 ඇතුළත අවම වශයෙන් දෙවරක්වත් පැමිණේ", "වසරකට පසු පමණි", "මාස 6කට පසු", "පාසල් යන වයසේදී", "නවජ රෝග ලක්ෂණ හඳුනාගැනීම හා නිවැරදි මව්කිරි දීම තහවුරු කිරීම මෙහි අරමුණයි."),
        q("වෛද්‍ය නිර්දේශයකින් තොරව නිතර ප්‍රතිජීවක ඖෂධ (Antibiotics) අඩු මාත්‍රාවලින් හෝ අසම්පූර්ණව ගැනීම නිසා ඇතිවන ගෝලීය සෞඛ්‍ය අර්බුදය කුමක්ද?", "ප්‍රතිජීවක ප්‍රතිරෝධීතාව (Antibiotic Resistance / AMR)", "ප්‍රතිශක්තිය වැඩිවීම", "වෛරස් සම්පූර්ණයෙන් වඳ වීම", "විටමින් අධික වීම", "සෙම්ප්‍රතිශ්‍යාව වැනි වෛරස් රෝගවලට ප්‍රතිජීවක ක්‍රියා නොකරන අතර අනවශ්‍ය භාවිතයෙන් බැක්ටීරියා ඖෂධවලට ඔරොත්තු දීමට පටන් ගනී."),
        q("වසංගත හෝ ආපදා අවස්ථාවලදී ප්‍රජාව තුළ සාමූහිකව පිරිසිදුකම පවත්වා ගැනීම සඳහා පාසල හා ගම එක්ව ක්‍රියාත්මක කළ යුතු පියවර කුමක්ද?", "කාණු පද්ධති ශුද්ධ පවිත්‍ර කර, වතුර රැඳෙන ස්ථාන ඉවත් කර, ජනතාව දැනුවත් කිරීමේ ශ්‍රමදාන පැවැත්වීම", "කසළ පාර අයිනට විසි කිරීම", "මදුරු තෙල් ගිනි තැබීම", "පාසල වසා නිදා ගැනීම", "ප්‍රජා සහභාගීත්වය (Community Participation) මහජන සෞඛ්‍ය වැඩසටහන් සාර්ථක වීමේ රහසයි."),
        q("කැලෑ ප්‍රදේශවල හෝ ජල මාර්ග අසල කටයුතු කිරීමෙන් පසු දරුණු උණ, මාංශ පේශි වේදනාව (විශේෂයෙන් කෙණ්ඩා පෙරළීමේ වේදනාව) සහ ඇස් රතු වීම ඇති වන්නේ කුමන රෝගයේදීද?", "මී උණ හෙවත් ලෙප්ටොස්පයිරෝසිස් රෝගයේදී", "සරම්ප රෝගයේදී", "පැපොල රෝගයේදී", "බරවා රෝගයේදී", "මී උණ උග්‍ර වූ විට වකුගඩු හා අක්මාව අකර්මණ්‍ය වී මරණය සිදුවිය හැකි බැවින් වහාම රෝහල් ගත විය යුතුය."),
        q("මැලේරියාව හා ඩෙංගු වැනි මදුරුවන්ගෙන් බෝවන රෝගවලින් රාත්‍රී නින්දේදී ආරක්ෂා වීමට භාවිත කළ හැකි වඩාත්ම ආරක්ෂිත ක්‍රමය කුමක්ද?", "ඖෂධ ගැල්වූ මදුරු දැලක් (ITN / LLIN) යට නිදා ගැනීම", "දොර ජනෙල් සම්පූර්ණයෙන් වසා දැමීම", "මදුරු කොයිල් ගණනාවක් කාමරය තුළ දැල්වීම", "විදුලි පහන් දල්වා තැබීම", "සංවෘත කාමරවල මදුරු කොයිල් දුම ආඝ්‍රාණය කිරීම දරුවන්ගේ පෙනහලුවලට හානිකර වන බැවින් මදුරු දැල ඉතා ආරක්ෂිතය."),
        q("ප්‍රතිශක්තිකරණ වැඩසටහනේදී මාතෘ පිටගැස්ම හා නවජ පිටගැස්ම වැළැක්වීම සඳහා ගැබිණි මව්වරුන්ට ලබාදෙන එන්නත කුමක්ද?", "පිටගැස්ම ටොක්සොයිඩ් එන්නත (Tetanus Toxoid — TT)", "BCG එන්නත", "MMR එන්නත", "රේබීස් එන්නත", "මවට එන්නත ලබාදීමෙන් නිපදවෙන ප්‍රතිදේහ වැදෑමහ හරහා දරුවාට ගොස් උපතේදී පෙකණිවැල හරහා සිදුවන පිටගැස්ම වළකාලයි."),
        q("ශ්‍රී ලංකාවේ දරුවෙකුට වයස මාස 4දී පංච සංයුජ එන්නත සමග අමතරව ලබාදෙන පෝලියෝ එන්නත කුමක්ද?", "අක්‍රීය පෝලියෝ එන්නත (fIPV — Fractional Inactivated Polio Vaccine)", "BCG එන්නත", "aTd එන්නත", "හෙපටයිටිස් A එන්නත", "මුඛ පෝලියෝ බිංදු (OPV) සමග IPV ලබාදීමෙන් පෝලියෝ වෛරස් සියලුම ප්‍රභේදවලින් පූර්ණ ආරක්ෂාව සැපයේ."),
        q("රෝගියෙකුගේ කැස්ස, කිවිසුම් සහ කතා කරන විට පිටවන කෙළ බිඳිති මගින් පැතිරෙන ශ්වසන බෝවන රෝග කාණ්ඩය කුමක්ද?", "ක්ෂය රෝගය, ඉන්ෆ්ලුවෙන්සා, සරම්ප සහ COVID-19", "මැලේරියාව සහ බරවා", "මී උණ සහ පිටගැස්ම", "කොළරාව සහ කොකුපණු රෝගය", "මෙම රෝග පාලනය කිරීමට මුඛ ආවරණ (Masks) පැළඳීම හා වාතාශ්‍රය ඇති ස්ථානවල රැඳීම ඉතා වැදගත් වේ."),
        q("ලිංගිකව නොව අසාමාන්‍ය හේතුවක් වන සමීප ස්පර්ශයෙන්, හවුලේ පනා හා කොට්ට භාවිතයෙන් පාසල් සිසුන් අතර පහසුවෙන් පැතිරෙන පරපෝෂිත ගැටලුව කුමක්ද?", "හිසේ උකුණන් (Pediculosis capitis)", "මැලේරියාව", "කොළරාව", "දියවැඩියාව", "නිතිපතා හිසකෙස් පිරිසිදුව තබාගැනීම සහ වෛද්‍ය නිර්දේශිත උකුණු නාශක භාවිතයෙන් මෙය සම්පූර්ණයෙන් පාලනය කළ හැක."),
        q("සෞඛ්‍යාරක්ෂිත නොවන ආපනශාලාවක් පිළිබඳව පැමිණිලි කිරීමට හෝ ආහාර සුරක්ෂිතතාව තහවුරු කිරීමට බලය ඇති පනත කුමක්ද?", "1980 අංක 26 දරන ආහාර පනත (Food Act of Sri Lanka)", "1950 මෝටර් රථ පනත", "1978 විදුලි පනත", "2006 දුම්කොළ පනත", "කල් ඉකුත් වූ හෝ අපිරිසිදු ආහාර අලෙවි කරන වෙළඳුන්ට එරෙහිව නීතිමය පියවර ගැනීමට මෙම පනත PHI වරුන්ට බලය දෙයි."),
        q("ජලය හා සම්බන්ධ බෝවන රෝග අතරින් 'ජලය හිඟකම නිසා සිරුර හා දෑත් නිසි ලෙස සේදීමට නොහැකි වීමෙන්' පැතිරෙන රෝග (Water-washed Diseases) මොනවාද?", "ඇස් රුදාව (Trachoma/Conjunctivitis), කසන රෝගය (Scabies) සහ සමේ දිලීර ආසාදන", "ඩෙංගු සහ මැලේරියාව", "කොළරාව පමණි", "ජලභීතිකාව", "ප්‍රමාණවත් පිරිසිදු ජල සැපයුමක් තිබීම පෞද්ගලික ස්වස්ථතාව රැකගනිමින් මෙම රෝග වළකාලයි."),
        q("වසර ගණනාවක් පුරා ශ්‍රී ලංකාව තුළ සාර්ථකව ක්‍රියාත්මක වූ ජාතික ප්‍රතිශක්තිකරණ වැඩසටහන (EPI) මගින් දැනට සම්පූර්ණයෙන්ම වඳ වී ගොස් හෝ තුරන් කර ඇති රෝග මොනවාද?", "වසූරිය (Smallpox), පෝලියෝ (Polio) සහ මාතෘ හා නවජ පිටගැස්ම", "ඩෙංගු සහ දියවැඩියාව", "ඇදුම සහ අධි රුධිර පීඩනය", "සෙම්ප්‍රතිශ්‍යාව", "ඉහළ එන්නත් ප්‍රතිශතයක් පවත්වා ගැනීම හේතුවෙන් ශ්‍රී ලංකාව දකුණු ආසියාවේ ආදර්ශමත් සෞඛ්‍ය රටක් බවට පත්ව ඇත."),
        q("බෝවන රෝගයක් පැතිර යන විට 'සෞඛ්‍ය සාක්ෂරතාව' (Health Literacy) ප්‍රජාව සතු වීම වැදගත් වන්නේ මන්ද?", "රෝගය බෝවන ආකාරය, රෝග ලක්ෂණ හා නිවැරදි වැළැක්වීමේ පියවර වටහාගෙන මිථ්‍යා මතවලට නොරැවටී ක්‍රියා කිරීමට", "අසත්‍ය කටකතා පැතිරවීමට", "රෝහල් මගහැරීමට", "එන්නත් ප්‍රතික්ෂේප කිරීමට", "නිවැරදි විද්‍යාත්මක සෞඛ්‍ය දැනුම ප්‍රජාව තුළ තිබීම වසංගත පාලනය කිරීමේ ශක්තිමත්ම අවියයි.")
    )
}
